Analyze this Python metaclass code. What does it do, and what will the assertions produce?

```python
class ValidatedMeta(type):
    def __new__(mcs, name, bases, namespace):
        for key, value in namespace.items():
            if isinstance(value, type) and issubclass(value, Validator):
                namespace[key] = value()
        cls = super().__new__(mcs, name, bases, namespace)
        cls._fields = [
            k for k, v in namespace.items()
            if isinstance(v, Validator)
        ]
        return cls

class Validator:
    def __init__(self):
        self.value = None
    def __set_name__(self, owner, name):
        self.name = name
    def __get__(self, obj, objtype=None):
        return self.value if obj is None else obj.__dict__.get(self.name)
    def __set__(self, obj, value):
        self.validate(value)
        obj.__dict__[self.name] = value
    def validate(self, value):
        pass

class PositiveInt(Validator):
    def validate(self, value):
        if not isinstance(value, int) or value <= 0:
            raise ValueError(f"{self.name} must be a positive integer")

class User(metaclass=ValidatedMeta):
    age = PositiveInt
    score = PositiveInt

u = User()
u.age = 25
u.score = 100
assert u.age == 25
assert u.score == 100
assert User._fields == ['age', 'score']
try:
    u.age = -1
    assert False, "Should have raised"
except ValueError:
    pass
```

