This TypeScript code implements a type-level state machine. Explain what compile-time guarantees it provides and trace through the valid/invalid transitions.

```typescript
interface DoorStates {
  open: { close: 'closed' };
  closed: { open: 'open'; lock: 'locked' };
  locked: { unlock: 'closed' };
}

type Transition<
  S extends keyof DoorStates,
  A extends keyof DoorStates[S]
> = DoorStates[S][A];

class Door<S extends keyof DoorStates = 'closed'> {
  private state!: S;

  transition<A extends keyof DoorStates[S]>(
    action: A
  ): Door<DoorStates[S][A] & keyof DoorStates> {
    return new Door() as any;
  }
}

const door = new Door();
const opened = door.transition('open');       // Door<'open'>
const closed = opened.transition('close');     // Door<'closed'>
const locked = closed.transition('lock');      // Door<'locked'>
const unlocked = locked.transition('unlock');  // Door<'closed'>
// locked.transition('open');  // Compile error!
```

